python3 - <<'PY'
from pathlib import Path
import re, json, collections
root=Path('.')
kt=[p for p in root.rglob('*.kt') if '/build/' not in str(p) and '/.gradle/' not in str(p)]
main=[p for p in kt if '/src/main/' in str(p)]
print('=== MODULES ===')
settings=Path('settings.gradle.kts').read_text(errors='ignore')
mods=re.findall(r'include\("([^"]+)"\)',settings)
print('MODULES',mods)
print('=== MODULE DEPENDENCIES ===')
for b in sorted(root.rglob('build.gradle.kts')):
    if '/build/' in str(b): continue
    txt=b.read_text(errors='ignore')
    deps=re.findall(r'project\("([^"]+)"\)',txt)
    if deps: print(str(b), '->', deps)
print('=== LARGEST MAIN KOTLIN FILES ===')
rows=[]
for p in main:
    txt=p.read_text(errors='ignore'); lines=txt.splitlines()
    funcs=len(re.findall(r'^\s*(?:override\s+|private\s+|internal\s+|public\s+|protected\s+|suspend\s+|inline\s+|tailrec\s+)*fun\s+',txt,re.M))
    classes=len(re.findall(r'^\s*(?:data\s+|sealed\s+|enum\s+|internal\s+|private\s+|public\s+|abstract\s+|open\s+)*(?:class|object|interface)\s+',txt,re.M))
    inject=len(re.findall(r'@Inject|@ApplicationContext|@Singleton',txt))
    rows.append((len(lines),funcs,classes,inject,str(p)))
for row in sorted(rows,reverse=True)[:35]: print('LOC_FUN_CLASS_DI',*row)
print('=== GOD OBJECT RISK CANDIDATES ===')
for loc,funcs,classes,inject,p in sorted(rows,reverse=True):
    if loc>=450 or funcs>=25 or inject>=10:
        print('GOD_RISK',loc,funcs,classes,inject,p)
print('=== OWNERSHIP: BleScanner LIFECYCLE CALLS ===')
for p in main:
    txt=p.read_text(errors='ignore')
    for i,l in enumerate(txt.splitlines(),1):
        if re.search(r'bleScanner\.(startScanning|startFocusedScan|stopScanning|resumePassiveScan)',l): print(f'{p}:{i}:{l.strip()}')
print('=== SERVICE START/STOP COMMAND SITES ===')
for p in main:
    txt=p.read_text(errors='ignore')
    for i,l in enumerate(txt.splitlines(),1):
        if any(x in l for x in ['startForegroundService(', '.startService(', 'ScannerServiceController.start(', 'ScannerServiceController.stop(', 'ACTION_START','ACTION_STOP']):
            print(f'{p}:{i}:{l.strip()}')
print('=== CONCURRENCY / LIFECYCLE SMELLS ===')
patterns=['GlobalScope','runBlocking','Thread.sleep','Executors.new','CoroutineScope(','observeForever','registerReceiver(','unregisterReceiver(','startForegroundService(','startService(']
for pat in patterns:
    hits=[]
    for p in main:
        for i,l in enumerate(p.read_text(errors='ignore').splitlines(),1):
            if pat in l: hits.append(f'{p}:{i}:{l.strip()}')
    print('PATTERN',pat,'COUNT',len(hits))
    for h in hits[:30]: print(h)
print('=== TODO FIXME HACK / SUPPRESSIONS ===')
for pat in ['TODO','FIXME','HACK','@Suppress']:
    hits=[]
    for p in main:
        for i,l in enumerate(p.read_text(errors='ignore').splitlines(),1):
            if pat in l: hits.append(f'{p}:{i}:{l.strip()}')
    print('PATTERN',pat,'COUNT',len(hits))
    for h in hits[:50]: print(h)
print('=== PHASE 2 KEY FILE METRICS ===')
for name in ['core/data/src/main/java/io/blueeye/service/ScannerService.kt','core/data/src/main/java/io/blueeye/scanner/BleScanner.kt','core/data/src/main/java/io/blueeye/core/data/scanner/AndroidScannerRuntimeController.kt','core/data/src/main/java/io/blueeye/service/ScannerServiceController.kt']:
    p=Path(name)
    if p.exists():
        txt=p.read_text(errors='ignore')
        print(name,'LOC',len(txt.splitlines()),'FUN',len(re.findall(r'\bfun\s+',txt)),'CLASSES',len(re.findall(r'\b(class|object|interface)\s+',txt)))
print('=== DOC INVENTORY ===')
for p in sorted(Path('docs').glob('*.md')):
    txt=p.read_text(errors='ignore')
    print('DOC',p,'LINES',len(txt.splitlines()),'PHASE2',('Phase 2' in txt or 'PHASE 2' in txt),'PHASE3',('Phase 3' in txt or 'PHASE 3' in txt),'HANDOFF',('handoff' in txt.lower()))
for p in [Path('README.md'),Path('AGENTS.md'),Path('docs/STABILITY_RECOVERY_GUIDE.md'),Path('docs/STABLE_CORE_PREIMPLEMENTATION_AUDIT.md'),Path('docs/QUALITY_GATE.md'),Path('docs/PRODUCT_GOAL.md')]:
    if p.exists():
        txt=p.read_text(errors='ignore')
        print('DOC_STATUS',p,'LINES',len(txt.splitlines()))
        for i,l in enumerate(txt.splitlines(),1):
            if re.search(r'Phase 2|Phase 3|NEXT ACTION|Stable Core|device acceptance|software gate|PASS|pending',l,re.I): print(f'{p}:{i}:{l.strip()}')
print('=== STATIC_AUDIT_DONE ===')
PY
